namespace remora {
static constexpr const char* Api="https://api.github.com/repos/ibnusina339/Remora/releases/latest";
static constexpr const char* Prefix="https://github.com/ibnusina339/Remora/releases/download/";
static OtaStatus status;static std::mutex mutex;static std::atomic<bool>cancelled{false};static std::string imageUrl,expectedHash;static int expectedSize=0;
static void set(const std::string&m,int progress=-1){std::lock_guard<std::mutex>l(mutex);status.message=m;if(progress>=0)status.progress=progress;}
OtaStatus otaStatus(){std::lock_guard<std::mutex>l(mutex);return status;}void otaCancel(){cancelled=true;}
static std::string str(const cJSON*j,const char*key){auto v=cJSON_GetObjectItemCaseSensitive(j,key);return cJSON_IsString(v)?v->valuestring:"";}
static esp_http_client_handle_t open(const std::string&url){esp_http_client_config_t c{};c.url=url.c_str();c.crt_bundle_attach=esp_crt_bundle_attach;c.timeout_ms=15000;c.buffer_size=2048;c.keep_alive_enable=true;c.max_redirection_count=8;auto h=esp_http_client_init(&c);if(!h)return nullptr;esp_http_client_set_header(h,"User-Agent","Remora-ESP32C6");esp_http_client_set_header(h,"Accept","application/json");if(esp_http_client_open(h,0)!=ESP_OK){esp_http_client_cleanup(h);return nullptr;}esp_http_client_fetch_headers(h);int code=esp_http_client_get_status_code(h);for(int i=0;i<8&&code>=300&&code<400;i++){if(esp_http_client_set_redirection(h)!=ESP_OK)break;esp_http_client_close(h);if(esp_http_client_open(h,0)!=ESP_OK)break;esp_http_client_fetch_headers(h);code=esp_http_client_get_status_code(h);}if(code!=200){esp_http_client_close(h);esp_http_client_cleanup(h);return nullptr;}return h;}
static std::string get(const std::string&url,size_t limit){auto h=open(url);if(!h)return {};std::string body;char b[1024];while(!cancelled){int n=esp_http_client_read(h,b,sizeof(b));if(n<0){body.clear();break;}if(!n)break;if(body.size()+n>limit){body.clear();break;}body.append(b,n);}esp_http_client_close(h);esp_http_client_cleanup(h);return body;}
static void checkTask(void*){cancelled=false;set("Memeriksa GitHub Releases...");auto body=get(Api,24576);auto j=cJSON_Parse(body.c_str());bool ok=false;if(j&&!cJSON_IsTrue(cJSON_GetObjectItem(j,"prerelease"))&&!cJSON_IsTrue(cJSON_GetObjectItem(j,"draft"))){auto version=str(j,"tag_name");auto next=SemVer::parse(version),current=SemVer::parse(esp_app_get_description()->version);if(next.valid&&next.pre.empty()&&next.compare(current)>0){std::string manifest;auto assets=cJSON_GetObjectItem(j,"assets");cJSON*a; cJSON_ArrayForEach(a,assets){auto name=str(a,"name"),url=str(a,"browser_download_url");if(url.rfind(Prefix,0)!=0)continue;if(name=="manifest.json")manifest=url;if(name=="remora-esp32c6.bin")imageUrl=url;}auto text=get(manifest,4096);auto m=cJSON_Parse(text.c_str());if(m){expectedHash=str(m,"sha256");auto size=cJSON_GetObjectItem(m,"size");expectedSize=cJSON_IsNumber(size)?size->valueint:0;auto assetVersion=SemVer::parse(str(m,"version"));ok=str(m,"board")=="esp32c6-supermini-k2"&&str(m,"asset")=="remora-esp32c6.bin"&&assetVersion.valid&&assetVersion.compare(next)==0&&expectedHash.size()==64&&expectedSize>0&&!imageUrl.empty();cJSON_Delete(m);}if(ok){std::lock_guard<std::mutex>l(mutex);status.available=true;status.version=version;status.message="Update tersedia. Hijau: pasang.";}}else set("Firmware sudah terbaru.");}if(j)cJSON_Delete(j);{std::lock_guard<std::mutex>l(mutex);if(!ok&&status.message=="Memeriksa GitHub Releases...")status.message="Release/manifest belum tersedia.";status.busy=false;}vTaskDelete(nullptr);}
static void installTask(void*){cancelled=false;set("Mengunduh firmware...",0);auto part=esp_ota_get_next_update_partition(nullptr);esp_ota_handle_t ota=0;bool begun=false,ok=part&&expectedSize>0&&expectedSize<=int(part->size);auto h=ok?open(imageUrl):nullptr;ok=h!=nullptr;mbedtls_sha256_context sha;mbedtls_sha256_init(&sha);mbedtls_sha256_starts(&sha,0);int received=0;uint8_t b[2048];std::string header;while(ok&&!cancelled){int n=esp_http_client_read(h,(char*)b,sizeof(b));if(n<0){ok=false;break;}if(!n)break;if(received+n>expectedSize){ok=false;break;}if(!begun){header.append((char*)b,n);const size_t offset=sizeof(esp_image_header_t)+sizeof(esp_image_segment_header_t);if(header.size()<offset+sizeof(esp_app_desc_t))continue;esp_app_desc_t desc;memcpy(&desc,header.data()+offset,sizeof(desc));auto v=SemVer::parse(std::string(desc.version,strnlen(desc.version,sizeof(desc.version))));auto wanted=SemVer::parse(otaStatus().version);if(desc.magic_word!=ESP_APP_DESC_MAGIC_WORD||!v.valid||v.compare(wanted)!=0||strncmp(desc.project_name,"Remora",sizeof(desc.project_name))!=0){ok=false;break;}ok=esp_ota_begin(part,expectedSize,&ota)==ESP_OK;if(!ok)break;begun=true;mbedtls_sha256_update(&sha,(const uint8_t*)header.data(),header.size());ok=esp_ota_write(ota,header.data(),header.size())==ESP_OK;received=header.size();header.clear();}else{mbedtls_sha256_update(&sha,b,n);ok=esp_ota_write(ota,b,n)==ESP_OK;received+=n;}set("Mengunduh firmware...",received*100/expectedSize);taskYIELD();}
 if(h){esp_http_client_close(h);esp_http_client_cleanup(h);}uint8_t digest[32];mbedtls_sha256_finish(&sha,digest);mbedtls_sha256_free(&sha);char hex[65];for(int i=0;i<32;i++)snprintf(hex+i*2,3,"%02x",digest[i]);ok=ok&&!cancelled&&begun&&received==expectedSize&&expectedHash==hex;if(ok){ok=esp_ota_end(ota)==ESP_OK;begun=false;}if(!ok&&begun)esp_ota_abort(ota);if(ok)ok=esp_ota_set_boot_partition(part)==ESP_OK;if(ok){set("Update selesai. Restart...",100);vTaskDelay(pdMS_TO_TICKS(1000));esp_restart();}else set(cancelled?"Update dibatalkan; firmware lama tetap aktif.":"Update gagal/diverifikasi gagal.");{std::lock_guard<std::mutex>l(mutex);status.busy=false;}vTaskDelete(nullptr);}
void otaCheck(){if(!networkConnected()){set("Wi-Fi belum terhubung.");return;}std::lock_guard<std::mutex>l(mutex);if(status.busy)return;status.busy=true;status.available=false;if(xTaskCreate(checkTask,"ota-check",8192,nullptr,3,nullptr)!=pdPASS){status.busy=false;status.message="Memori OTA tidak cukup.";}}
void otaInstall(){std::lock_guard<std::mutex>l(mutex);if(status.busy||!status.available)return;status.busy=true;if(xTaskCreate(installTask,"ota-install",8192,nullptr,3,nullptr)!=pdPASS){status.busy=false;status.message="Memori OTA tidak cukup.";}}
}
